// Intuit signs the raw request body: base64(HMAC-SHA256(body, Webhooks Verifier Token)),
// sent in the `intuit-signature` header. Token: Intuit Developer portal → your app → Webhooks.
const crypto = require('crypto');

const INTUIT_VERIFIER_TOKEN = ''; // fallback only; prefer the n8n Variable INTUIT_VERIFIER_TOKEN
function setting(name, fallback) {
  // n8n Variables win; the constant above is the fallback for plans without Variables.
  try { const v = $vars[name]; if (v) return String(v); } catch (e) {}
  return fallback;
}

const verifier = setting('INTUIT_VERIFIER_TOKEN', INTUIT_VERIFIER_TOKEN);
if (!verifier) throw new Error('INTUIT_VERIFIER_TOKEN is not configured');

const item = $input.first();
let rawBody;
if (item.binary && item.binary.data) {
  // n8n Cloud keeps binary data out of band: item.binary.data.data is a storage
  // reference, not the bytes, so always go through the helper.
  rawBody = await this.helpers.getBinaryDataBuffer(0, 'data');
} else {
  // Webhook "Raw Body" option is off. Re-serializing may not match Intuit's bytes.
  rawBody = Buffer.from(JSON.stringify(item.json.body ?? {}), 'utf8');
}

const headers = item.json.headers || {};
const provided = String(headers['intuit-signature'] || '');
const expected = crypto.createHmac('sha256', verifier).update(rawBody).digest('base64');

const a = Buffer.from(provided);
const b = Buffer.from(expected);
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
  throw new Error('Invalid intuit-signature — dropping event (check INTUIT_VERIFIER_TOKEN and the Raw Body option)');
}

return [{ json: { body: JSON.parse(rawBody.toString('utf8')) } }];

// Intuit's current webhook format is CloudEvents (mandatory since 15 May 2026), a JSON array:
//   [{ "type": "qbo.payment.created.v1", "intuitentityid": "182", "intuitaccountid": "<realmId>", "time": "...", "data": {} }]
// The legacy format is still accepted in case the app hasn't been switched over:
//   { "eventNotifications": [{ "realmId": "...", "dataChangeEvent": { "entities": [{ "name": "Payment", "id": "182", "operation": "Create" }] } }] }
const ERP_BASE_URL = 'https://illumenatelighting.v.frappe.cloud';
const QBO_API_BASE = 'https://quickbooks.api.intuit.com'; // Intuit sandbox company: https://sandbox-quickbooks.api.intuit.com
function setting(name, fallback) {
  // n8n Variables win; the constant above is the fallback for plans without Variables.
  try { const v = $vars[name]; if (v) return String(v); } catch (e) {}
  return fallback;
}

const config = {
  erp_base_url: setting('ILL_ERP_BASE_URL', ERP_BASE_URL).replace(/\/+$/, ''),
  qbo_api_base: setting('QBO_API_BASE', QBO_API_BASE).replace(/\/+$/, ''),
};
const VERBS = { created: 'Create', updated: 'Update', deleted: 'Delete', voided: 'Void', merged: 'Merge' };

const events = [];
for (const item of $input.all()) {
  const body = item.json.body;
  const list = Array.isArray(body) ? body : [body];
  for (const ev of list) {
    if (!ev || typeof ev !== 'object') continue;
    if (ev.specversion || ev.type) {
      // qbo.<entity>.<verb>.v1
      const parts = String(ev.type || '').toLowerCase().split('.');
      if (parts[1] !== 'payment') continue;
      const data = ev.data || {};
      events.push({
        realmId: String(ev.intuitaccountid || ''),
        id: String(ev.intuitentityid || ''),
        operation: VERBS[parts[2]] || null,
        lastUpdated: ev.time || null,
        deletedId: data.deletedId || data.deletedEntityId ? String(data.deletedId || data.deletedEntityId) : null,
        event_type_raw: ev.type,
      });
      continue;
    }
    for (const n of ev.eventNotifications || []) {
      for (const e of (n.dataChangeEvent && n.dataChangeEvent.entities) || []) {
        if (e.name !== 'Payment') continue;
        events.push({
          realmId: String(n.realmId || ''),
          id: String(e.id || ''),
          operation: e.operation || null,
          lastUpdated: e.lastUpdated || null,
          deletedId: e.deletedId ? String(e.deletedId) : null,
          event_type_raw: e.operation,
        });
      }
    }
  }
}

// One item per payment: the fetch below reads the payment's *current* state, so a
// Create + Update in the same delivery only needs one call. A Delete/Void wins.
const byId = new Map();
for (const e of events) {
  if (!e.id || !e.realmId || !e.operation) continue;
  const prev = byId.get(e.id);
  const isRemoval = (op) => op === 'Delete' || op === 'Void';
  if (!prev || !isRemoval(prev.operation)) byId.set(e.id, e);
}
return [...byId.values()].map((e) => ({ json: { ...e, ...config } }));

// Deleted payments can't be fetched from QBO; forward the id only.
return $input.all().map((item) => ({
  json: {
    qbo_payment_id: item.json.id,
    event_type: 'Delete',
    deleted: true,
    realm_id: item.json.realmId,
    last_updated: item.json.lastUpdated,
    erp_base_url: item.json.erp_base_url,
  },
}));

// Normalize the QBO Payment into the ERPNext payload. Runs once per item; the paired
// item gives us the originating webhook event.
const payment = $input.item.json.Payment || $input.item.json;
const source = $('Split Payment Entities').item.json;

const invoiceIds = [];
let applied = 0;
for (const line of payment.Line || []) {
  const linked = (line.LinkedTxn || []).filter((lt) => lt.TxnType === 'Invoice' && lt.TxnId);
  for (const lt of linked) invoiceIds.push(String(lt.TxnId));
  if (linked.length) applied += Number(line.Amount || 0);
}
const uniqueInvoiceIds = [...new Set(invoiceIds)];

let eventType = source.operation || 'Update';
if (eventType === 'Void') eventType = 'Delete';

return {
  json: {
    qbo_payment_id: String(payment.Id || source.id),
    event_type: eventType,
    // A voided payment comes back with TotalAmt 0; ERPNext cancels the Payment Entry for it.
    amount: Number(payment.TotalAmt || 0),
    applied_amount: Math.round(applied * 100) / 100,
    txn_date: payment.TxnDate || null,
    qbo_invoice_id: uniqueInvoiceIds[0] || null,
    qbo_invoice_ids: uniqueInvoiceIds,
    customer_qbo_id: payment.CustomerRef ? String(payment.CustomerRef.value) : null,
    merged_from_id: source.deletedId || null,
    deleted: false,
    realm_id: source.realmId || null,
    last_updated: (payment.MetaData && payment.MetaData.LastUpdatedTime) || source.lastUpdated || null,
    erp_base_url: source.erp_base_url,
  },
};

// Sign the exact JSON string that will be sent. ERPNext recomputes
// HMAC-SHA256(raw_body, secret) and compares hex digests.
const crypto = require('crypto');

const QBO_WEBHOOK_SECRET = ''; // fallback only; prefer the n8n Variable QBO_WEBHOOK_SECRET
function setting(name, fallback) {
  // n8n Variables win; the constant above is the fallback for plans without Variables.
  try { const v = $vars[name]; if (v) return String(v); } catch (e) {}
  return fallback;
}

const secret = setting('QBO_WEBHOOK_SECRET', QBO_WEBHOOK_SECRET); // same value as ilL-QBO-Settings → Webhook Shared Secret
if (!secret) throw new Error('QBO_WEBHOOK_SECRET is not configured');

return $input.all().map((item) => {
  const { erp_base_url, ...payload } = item.json;
  const body = JSON.stringify(payload);
  const signature = crypto.createHmac('sha256', secret).update(body, 'utf8').digest('hex');
  return {
    json: {
      body,
      signature,
      url: `${erp_base_url}/api/method/illumenate_lighting.illumenate_lighting.api.qbo_sync.receive_payment_event`,
      qbo_payment_id: payload.qbo_payment_id,
      event_type: payload.event_type,
    },
  };
});

// Shape an alert. Wire the next node to Slack / Email using {{ $json.subject }} / {{ $json.text }}.
// Reached from a failed QBO fetch (error output) or a non-success ERPNext response.
return $input.all().map((item) => {
  const j = item.json || {};
  const r = j.message && typeof j.message === 'object' ? j.message : j;
  let error = r.error || 'unknown';
  if (typeof error === 'object') error = error.message || JSON.stringify(error);
  let detail = typeof r.message === 'string' ? r.message : '';
  let payload = '';
  try { payload = $('Sign Request (HMAC)').item.json.body; } catch (e) {}
  let source = {};
  try { source = $('Split Payment Entities').item.json; } catch (e) {}
  return {
    json: {
      subject: `QBO → ERPNext payment sync failed: ${error}`,
      text: [
        `Error: ${error}`,
        `Detail: ${detail}`,
        `QBO Payment: ${source.id || 'n/a'} (${source.operation || 'n/a'})`,
        `Sync log: ${r.log || 'n/a'} (ERPNext → ilL-QBO-Sync-Log)`,
        payload ? `Payload: ${payload}` : '',
      ].filter(Boolean).join('\n'),
      raw: j,
    },
  };
});
